<template>
  <div class="mobile-page"><div class="mobile-head"><b>随手拍</b><span>粮食生产问题上报</span><el-tag size="small" type="success">定位可用</el-tag></div>
    <div class="form-card"><h3>现场问题快速上报</h3><el-form label-position="top"><el-form-item label="问题类型"><el-select v-model="form.type" style="width:100%"><el-option v-for="item in issueTypes" :key="item" :label="item" :value="item"/></el-select></el-form-item><el-form-item label="所在地区"><el-cascader v-model="form.region" :options="regionOptions" style="width:100%"/></el-form-item><el-form-item label="现场定位"><div class="location"><el-input v-model="form.location"/><el-button @click="locate">重新定位</el-button></div></el-form-item><el-form-item label="问题描述"><el-input v-model="form.description" type="textarea" :rows="4" maxlength="180" show-word-limit placeholder="请描述发现的问题、影响范围和建议措施"/></el-form-item><el-form-item label="现场照片"><div class="photos"><div v-for="photo in form.photos" :key="photo" class="photo"><span>{{ photo }}</span><i @click="removePhoto(photo)">×</i></div><el-button class="add-photo" @click="addPhoto">＋ 添加演示照片</el-button></div></el-form-item></el-form><div class="actions"><el-button @click="saveDraft">暂存草稿</el-button><el-button type="primary" @click="submit">提交上报</el-button></div></div>
    <div class="list-card"><div class="list-title"><b>我的上报记录</b><el-radio-group v-model="tab" size="small"><el-radio-button label="全部"/><el-radio-button label="处理中"/><el-radio-button label="已办结"/></el-radio-group></div><div v-for="item in filteredReports" :key="item.id" class="report-item"><div class="report-top"><el-tag size="small" :type="item.status === '已办结' ? 'success' : 'warning'">{{ item.status }}</el-tag><span>{{ item.time }}</span></div><b>{{ item.type }}</b><p>{{ item.regionName }} · {{ item.description }}</p><div class="report-bottom"><span>编号 {{ item.id }}</span><el-button link type="primary" @click="viewReport(item)">查看处理进度</el-button></div></div><el-empty v-if="!filteredReports.length" description="暂无记录"/></div>
    <el-dialog v-model="detailVisible" title="上报处理进度" width="480px"><template v-if="activeReport"><el-descriptions :column="1" border><el-descriptions-item label="问题类型">{{ activeReport.type }}</el-descriptions-item><el-descriptions-item label="所在地区">{{ activeReport.regionName }}</el-descriptions-item><el-descriptions-item label="当前状态"><el-tag type="warning">{{ activeReport.status }}</el-tag></el-descriptions-item><el-descriptions-item label="处理意见">{{ activeReport.opinion || '已转交属地农业农村部门核查，预计 1 个工作日内反馈。' }}</el-descriptions-item></el-descriptions></template></el-dialog>
  </div>
</template>
<script setup>
import { computed, reactive, ref } from 'vue'
import { ElMessage } from 'element-plus'
const issueTypes = ['撂荒地发现', '灾害受损', '病虫害', '违规占用耕地', '其他问题']
const regionOptions = [{ value: '阜阳市', label: '阜阳市', children: [{ value: '太和县', label: '太和县', children: [{ value: '旧县镇', label: '旧县镇' }] }] }, { value: '亳州市', label: '亳州市', children: [{ value: '涡阳县', label: '涡阳县' }] }, { value: '合肥市', label: '合肥市', children: [{ value: '肥西县', label: '肥西县' }] }]
const form = reactive({ type: '灾害受损', region: ['阜阳市', '太和县', '旧县镇'], location: '安徽省阜阳市太和县旧县镇（31.0214, 115.6248）', description: '', photos: ['田块现场.jpg'] })
const reports = ref([{ id: 'SNAP-20261012-001', type: '灾害受损', regionName: '阜阳市·太和县·旧县镇', description: '低温阴雨导致部分田块积水，建议尽快排水。', status: '处理中', time: '2026-10-12 16:30' }, { id: 'SNAP-20261008-006', type: '病虫害', regionName: '亳州市·涡阳县', description: '发现玉米叶片出现集中虫咬斑。', status: '已办结', time: '2026-10-08 09:15', opinion: '已安排植保技术员现场指导，完成防治。' }])
const tab = ref('全部'); const detailVisible = ref(false); const activeReport = ref(null)
const filteredReports = computed(() => reports.value.filter(item => tab.value === '全部' || item.status === tab.value))
const locate = () => { form.location = '安徽省阜阳市太和县旧县镇（31.0214, 115.6248）'; ElMessage.success('定位已更新') }
const addPhoto = () => { if (form.photos.length >= 3) return ElMessage.info('演示最多添加 3 张照片'); form.photos.push(`现场照片${form.photos.length + 1}.jpg`) }
const removePhoto = photo => { form.photos = form.photos.filter(item => item !== photo) }
const saveDraft = () => ElMessage.success('已暂存到随手拍草稿箱')
const submit = () => { if (!form.description.trim()) return ElMessage.warning('请填写问题描述'); reports.value.unshift({ id: `SNAP-20261013-${String(reports.value.length + 1).padStart(3, '0')}`, type: form.type, regionName: form.region.join('·'), description: form.description, status: '处理中', time: new Date().toLocaleString('zh-CN', { hour12: false }) }); form.description = ''; ElMessage.success('问题已提交，属地部门将及时处理') }
const viewReport = item => { activeReport.value = item; detailVisible.value = true }
</script>
<style lang="scss" scoped>
.mobile-page{max-width:560px;margin:0 auto;min-height:100%;background:#f5f7fa;padding:14px}.mobile-head{display:flex;align-items:center;gap:10px;background:#fff;padding:16px;border-radius:10px;color:#1f3c68}.mobile-head b{font-size:20px}.mobile-head span{flex:1}.form-card,.list-card{background:#fff;border-radius:10px;padding:16px;margin-top:12px}.form-card h3{margin:0 0 16px;color:#243b5a}.location{display:flex;gap:8px}.location .el-input{flex:1}.photos{display:flex;gap:8px;flex-wrap:wrap}.photo{position:relative;background:#eaf2fb;color:#315d8d;border-radius:6px;padding:14px 26px 14px 10px;font-size:12px}.photo i{position:absolute;right:7px;top:5px;font-style:normal;cursor:pointer}.add-photo{border:1px dashed #b7cbe1;color:#3c78b5}.actions{display:flex;justify-content:flex-end;gap:8px;margin-top:18px}.list-title{display:flex;align-items:center;justify-content:space-between;gap:8px}.report-item{border-top:1px solid #edf0f5;padding:13px 0}.report-top,.report-bottom{display:flex;align-items:center;justify-content:space-between;color:#98a2b3;font-size:12px}.report-item>b{display:block;color:#243b5a;margin-top:9px}.report-item p{color:#667085;font-size:13px;line-height:1.5;margin:6px 0}.report-bottom span{font-size:11px}
</style>
